const db = openDatabase();
let stopping = false;

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const POLL_MS = 100;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const nowIso = () => new Date().toISOString();

const heartbeatStmt = db.prepare('INSERT INTO heartbeat (id, at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET at = excluded.at');
function heartbeat(): void {
  try {
    heartbeatStmt.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
