  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
   WHERE id = (SELECT id FROM jobs WHERE status = 'queued' AND run_at <= ? ORDER BY seq ASC LIMIT 1)
   RETURNING *`,
);
const progressStmt = db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`);
const completeStmt = db.prepare(
  `UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?`,
);
