import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError {
  field: string;
  message: string;
}

class HttpError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public fields?: FieldError[],
  ) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  const text = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });
  res.end(text);
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields || err.code === 'invalid_request') error.fields = err.fields ?? [];
  send(res, err.status, { error });
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) tooLarge = true;
      else chunks.push(c);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, payload_hash, run_at, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
);
const selectHeartbeat = db.prepare('SELECT at FROM heartbeat WHERE id = 1');

function isIntInRange(v: unknown, min: number, max: number): boolean {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];

  const rawKey = req.headers['idempotency-key'];
  let key: string | null = null;
  if (rawKey !== undefined) {
    const k = Array.isArray(rawKey) ? rawKey.join(',') : rawKey;
    if (!KEY_RE.test(k)) fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
    else key = k;
  }

  const contentType = (req.headers['content-type'] ?? '').split(';')[0].trim().toLowerCase();
  const text = await readBody(req);
  let payload: { input: string; steps: number; failAttempts: number } | null = null;

  if (contentType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (text === null) {
    fields.push({ field: 'body', message: 'body is too large' });
  } else {
    let body: unknown;
    let parsed = true;
    try {
      body = JSON.parse(text);
    } catch {
      parsed = false;
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
    if (parsed) {
      if (typeof body !== 'object' || body === null || Array.isArray(body)) {
        fields.push({ field: 'body', message: 'body must be a JSON object' });
      } else {
        const obj = body as Record<string, unknown>;
        const before = fields.length;
        for (const k of Object.keys(obj)) {
          if (k !== 'input' && k !== 'steps' && k !== 'failAttempts') fields.push({ field: k, message: 'unknown field' });
        }
        const input = obj.input;
        if (input === undefined) fields.push({ field: 'input', message: 'input is required' });
        else if (typeof input !== 'string') fields.push({ field: 'input', message: 'input must be a string' });
        else if (input.length < 1 || input.length > 1000) fields.push({ field: 'input', message: 'input must be 1-1000 characters' });
        else if (input.trim() === '') fields.push({ field: 'input', message: 'input must not be only whitespace' });

        const steps = obj.steps === undefined ? 5 : obj.steps;
        if (!isIntInRange(steps, 1, 20)) fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
        const failAttempts = obj.failAttempts === undefined ? 0 : obj.failAttempts;
        if (!isIntInRange(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });

        if (fields.length === before) payload = { input: input as string, steps: steps as number, failAttempts: failAttempts as number };
      }
    }
  }

  if (fields.length > 0 || !payload) {
    throw new HttpError(400, 'invalid_request', 'The request is invalid.', fields);
  }

  const hash = JSON.stringify([payload.input, payload.steps, payload.failAttempts]);
  if (key !== null) {
    const existing = selectByKey.get(key) as JobRow | undefined;
    if (existing) {
      if (existing.payload_hash === hash) return send(res, 200, toJob(existing));
      throw new HttpError(409, 'idempotency_conflict', 'The Idempotency-Key was already used with a different payload.');
    }
  }

  const id = randomUUID();
  const now = new Date().toISOString();
  try {
    insertJob.run(id, payload.input, payload.steps, payload.failAttempts, key, key === null ? null : hash, now, now);
  } catch (err) {
    // Unique constraint race on the idempotency key: resolve against the winner.
    if (key !== null) {
      const existing = selectByKey.get(key) as JobRow | undefined;
      if (existing) {
        if (existing.payload_hash === hash) return send(res, 200, toJob(existing));
        throw new HttpError(409, 'idempotency_conflict', 'The Idempotency-Key was already used with a different payload.');
      }
    }
    throw err;
  }
  send(res, 201, toJob(selectById.get(id) as unknown as JobRow));
}

function methodNotAllowed(allowed: string[]): HttpError {
  return new HttpError(405, 'method_not_allowed', `Method not allowed. Allowed: ${allowed.join(', ')}.`);
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    const row = selectHeartbeat.get() as { at: number } | undefined;
    const up = !!row && Date.now() - row.at < 3000;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/' || pathname === '/index.html') {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = selectAll.all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (method === 'POST') return createJob(req, res);
    throw methodNotAllowed(['GET', 'POST']);
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    let id: string;
    try {
      id = decodeURIComponent(m[1]);
    } catch {
      throw new HttpError(404, 'not_found', 'Job not found.');
    }
    const row = selectById.get(id) as JobRow | undefined;
    if (!row) throw new HttpError(404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    if (err instanceof HttpError) return sendError(res, err);
    console.error(err);
    if (!res.headersSent) sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
    else res.end();
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    try {
      db.close();
    } catch {}
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

